seo_schema:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "IGRSUP kya hai aur iska pura naam kya hai?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "IGRSUP ka pura naam Inspector General of Registration and Stamps, Uttar Pradesh hai. Yeh UP Stamp aur Registration Department ka official portal hai jo igrsup.gov.in par milta hai. Yahan property registration, stamp duty payment, property search, encumbrance certificate aur e-stamp verification ki sevayein milti hain."
      }
    },
    {
      "@type": "Question",
      "name": "IGRSUP par Lucknow mein property search kaise karein?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "igrsup.gov.in par Sampatti Vivaran par click karein. Rural ya Urban option chunein. Rural ke liye district, tehsil, village aur khasra number bharein. Urban ke liye district aur property ID bharein. Captcha bharke submit karein. Sewa poori tarah muft hai."
      }
    },
    {
      "@type": "Question",
      "name": "Kya IGRSUP property search muft hai?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Haan, IGRSUP par basic property search bilkul muft hai aur iske liye login nahi chahiye. Sirf property ki details jaise district, tehsil, village, khasra number ya property ID chahiye. Encumbrance certificate ke liye 200-500 rupye lagte hain."
      }
    },
    {
      "@type": "Question",
      "name": "IGRSUP aur UP Bhulekh mein kya farak hai?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "IGRSUP Stamp aur Registration Department ka portal hai jo registered documents dikhata hai. UP Bhulekh Revenue Department ka portal hai jo khatauni aur maujuda malik dikhata hai. Poore verification ke liye dono check karna zaroori hai."
      }
    },
    {
      "@type": "Question",
      "name": "IGRSUP par kitne purane records milte hain?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "IGRSUP par digital records 2005 se aage ke milte hain, 2017 se data aur complete hai. 2005 se pehle ke lenden ke liye Sub-Registrar Office mein manual search karwani padti hai. IGRSUP Index feature 5 December 2017 ke baad ke liye address se search karne deta hai."
      }
    },
    {
      "@type": "Question",
      "name": "Lucknow mein 2026 mein stamp duty aur registry charge kitna hai?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Purush kharidar ke liye 7 percent stamp duty plus 1 percent registry. Mahila ke liye 1 crore tak ki property par 6 percent (usse upar 7 percent). July 2025 mein mahilaon ki 1 percent chhoot ki seema 10 lakh se badhakar 1 crore ki gayi. Blood relatives mein gift deed par sirf 5000 rupye flat."
      }
    },
    {
      "@type": "Question",
      "name": "Kya IGRSUP par e-stamp certificate satyapit kar sakte hain?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Haan, IGRSUP par E-Stamp Satyapan tool hai jo SHCIL portal par redirect karta hai. UIN, issue date aur duty type bharke verify karein. Yeh 30 second mein batata hai ki stamp asli hai ya nakli. Har property document lene se pehle yeh check zaroori hai."
      }
    },
    {
      "@type": "Question",
      "name": "Lucknow ki property ke liye konsa SRO sahi hai?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Lucknow mein paanch SRO hain - Lucknow Sadar, Sarojini Nagar, Malihabad, Mohanlalganj aur Bakshi Ka Talab. IGRSUP par Apna Karyalaya Janein feature se district, tehsil, gaon aur colony dalkar sahi SRO pata lagayein. Galat SRO property search aur EC fail hone ka sabse aam karan hai."
      }
    },
    {
      "@type": "Question",
      "name": "IGRSUP par result khali aaye to kya karein?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Pehle check karein urban ya rural sahi chuna. Tehsil aur khasra number sahi hai ya nahi. Gaon ki spelling official record jaisi hai. Agar sab sahi hai phir bhi result nahi aata to property 2005 se pehle ki ho sakti hai. Sub-Registrar Office mein manual search karwayein. Khali result ka matlab yeh kabhi na samjhein ki property par lenden nahi hai."
      }
    },
    {
      "@type": "Question",
      "name": "Kya IGRSUP se encumbrance certificate ke liye apply kar sakte hain?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Haan, IGRSUP par Bharmukt Pramanpatra ya Barah Sala ke liye online apply kar sakte hain. Property details aur avdhi (12 saal ya 30 saal) bharein. 200 se 500 rupye fees online bharein. Digital signed PDF 2 se 15 din mein mil jati hai. Baynama se pehle EC lena har kharidar ke liye zaroori hai."
      }
    }
  ]
}
